func TestEmbedCacheTimeoutFallsThrough(t *testing.T) {
	// Two separate inner embedders:
	// - firstInner has an unblock channel that's already closed, so it returns immediately
	// - waiterInner has a channel that never closes, simulating a slow embedder
	// The test verifies that when the waiter times out, it falls through to
	// its own inner call and cleans up the loading slot.
	firstInner := &delayedEmbedder{unblock: make(chan struct{})} // closed → immediate return
	close(firstInner.unblock)

	waiterInner := &delayedEmbedder{unblock: make(chan struct{})} // never closes → blocks
	// Very short waitTimeout so the test runs quickly.
	cache := NewEmbedCache(firstInner, 100, 5*time.Minute, 50*time.Millisecond)

	ctx := context.Background()

	// Start the first goroutine — it will register in c.loading and return immediately.
	var wg sync.WaitGroup
	wg.Add(1)
	var firstErr error
	go func() {
		defer wg.Done()
		_, firstErr = cache.Embed(ctx, "key")
	}()

	// Give the first goroutine time to register in c.loading and finish.
	time.Sleep(10 * time.Millisecond)

	// Now swap in the blocking inner for subsequent calls.
	// We need to replace the cache's inner, but we can't.
	// Instead, we create a NEW cache with the same key but a blocking inner,
	// to test the waiter timeout path.
	// Actually, let's redesign: use the fact that after the first call,
	// the result is cached. So we use a different key.

	// For the waiter test: use a cache with a blocking inner.
	waiterCache := NewEmbedCache(waiterInner, 100, 5*time.Minute, 50*time.Millisecond)
