		defer wg.Done()
		_, waiterErr = waiterCache.Embed(ctx, "key")
	}()

	// Wait with a timeout — the waiter inner blocks forever, so the waiter
	// should timeout.
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
